// config.js: what the shared map-quiz engine (main.js, contract.js) needs
// to know about Europe Quiz: the data (countries.js, generated by
// tools/build_map.py) and every text the engine shows. Static text (title,
// help, button labels before the script runs) is in index.html. Contract:
// shared/map-quiz/README.md.
import { MAP, COUNTRIES } from './countries.js';

const misclicks = (n) => (n ? ` · ${n} misclick${n === 1 ? '' : 's'}` : ' · no misclicks');

export default {
  map: MAP,
  items: COUNTRIES,
  rounds: [
    {
      key: 'countries',
      label: 'Countries',
      prompt: 'Find',
      ask: (c) => c.name,
      miss: (c) => c.name,
      done: ({ total, misses }) => `All ${total} countries found${misclicks(misses)}. Now the capitals: find each one's country.`,
    },
    {
      key: 'capitals',
      label: 'Capitals',
      prompt: 'Find the country whose capital is',
      ask: (c) => c.capital,
      miss: (c) => `${c.name} · ${c.capital}`,
      done: ({ total, misses }) => `All ${total} capitals found${misclicks(misses)}. Countries again, in a new order.`,
    },
  ],
  text: {
    intro: {
      mouse: 'Click the country with this name. Zoom: mouse wheel or pinch. Move: drag or two-finger scroll.',
      touch: 'Tap the country with this name. Pinch to zoom, drag to move.',
    },
    newGame: 'New game: counters at zero, countries first.',
    reset: 'Reset the quiz',
    resetArmed: 'Really reset? Counters and colours are cleared',
    mapError: 'The map could not be loaded. Reload the page to try again.',
    theme: (other, override) => ({
      label: `Switch to ${other} theme`,
      title: override ? `Back to the system setting (${other})` : `Switch to the ${other} theme`,
    }),
  },
};
